import AppKit
import SwiftUI

/// Lync's icons: one SVG per SF Symbol name the app uses, in Resources/Icons (generated by
/// brand/icons/generate.mjs, the same set the phone app draws). Code keeps asking for symbol
/// names; a name without a file falls back to the SF Symbol.
@MainActor
enum WIcon {
    private static var cache: [String: NSImage] = [:]
    private static var missing: Set<String> = []

    /// The icon for `name` as a template image (so `foregroundStyle` tints it), or nil.
    static func image(_ name: String) -> NSImage? {
        if let image = cache[name] { return image }
        if missing.contains(name) { return nil }
        guard let url = directory?.appendingPathComponent("\(name).svg"),
              let image = NSImage(contentsOf: url) else {
            missing.insert(name)
            return nil
        }
        image.isTemplate = true
        cache[name] = image
        return image
    }

    /// In the app, its Resources; in a development build or the snapshots (no bundle), the repo's.
    private static let directory: URL? = {
        if let bundled = Bundle.main.url(forResource: "Icons", withExtension: nil) { return bundled }
        let repo = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
            .appendingPathComponent("Resources/Icons")
        return FileManager.default.fileExists(atPath: repo.path) ? repo : nil
    }()
}

/// An icon by SF Symbol name, sized and placed like the symbol it stands in for: a hidden
/// `circle` symbol takes the surrounding `.font(...)` and sets the icon's box and baseline (so it
/// lines up in a `Label` the way a symbol does), and the icon takes `foregroundStyle`.
struct IconImage: View {
    let name: String

    init(_ name: String) { self.name = name }

    /// The icon's side against the circle symbol's: the icons fill about 5/6 of their 24 grid, so
    /// their outer shapes land where a symbol's would.
    static let scale: CGFloat = 1.2

    var body: some View {
        if let image = WIcon.image(name) {
            Image(systemName: "circle")
                .hidden()
                .overlay {
                    GeometryReader { proxy in
                        let side = proxy.size.height * Self.scale
                        Image(nsImage: image)
                            .renderingMode(.template)
                            .resizable()
                            .interpolation(.high)
                            .scaledToFit()
                            .frame(width: side, height: side)
                            .position(x: proxy.size.width / 2, y: proxy.size.height / 2)
                    }
                }
                .accessibilityHidden(true)
        } else {
            Image(systemName: name)
        }
    }
}
